import{_ as a,a as r,b as e,c as i,d as l,e as d}from"./chunks/history.CPoQGR9M.js";import{_ as o,o as h,c as s,a2 as c}from"./chunks/framework.CDA9RsCr.js";const g=JSON.parse('{"title":"产品介绍","description":"","frontmatter":{},"headers":[],"relativePath":"intro/product.md","filePath":"intro/product.md","lastUpdated":1794581028000}'),n={name:"intro/product.md"};function p(_,t,b,u,m,k){return h(),s("div",null,[...t[0]||(t[0]=[c('<h1 id="产品介绍" tabindex="-1">产品介绍 <a class="header-anchor" href="#产品介绍" aria-label="Permalink to &quot;产品介绍&quot;">​</a></h1><p>BiliLuckyDraw 是一个为 B 站直播间设计的桌面应用。开启后实时监听直播间弹幕：观众发送含指定口令的弹幕即视为参与，开奖时从所有参与者中随机抽取中奖者。整个过程自动完成，不需要人工记名单，公平透明。</p><p>除抽奖之外，它还把这几个原本要开一堆窗口的事收进同一个界面：直播画面、频道列表、实时弹幕、中奖名单。开播前不用来回切换浏览器和文档。</p><p>适合主播在日常直播、粉丝节或节日活动中即开即用。</p><ul><li>仓库：<a href="https://github.com/aDarkMaker/BiliLuckyDraw" target="_blank" rel="noreferrer">aDarkMaker/BiliLuckyDraw</a></li><li>下载：<a href="https://github.com/aDarkMaker/BiliLuckyDraw/releases" target="_blank" rel="noreferrer">Releases</a></li><li>许可证：<a href="https://github.com/aDarkMaker/BiliLuckyDraw/blob/main/LICENSE" target="_blank" rel="noreferrer">MIT</a> © 2025 aDarkMaker</li></ul><h2 id="它能做什么" tabindex="-1">它能做什么 <a class="header-anchor" href="#它能做什么" aria-label="Permalink to &quot;它能做什么&quot;">​</a></h2><ul><li>实时监控一个或多个直播间的弹幕</li><li>观众发送含口令的弹幕即视为参与，按 UID 去重（同一直播间多次发言只计一次）；口令留空则收集全部弹幕</li><li>一键开奖，随机抽取指定数量的中奖者，并自动写入该配置的历史记录</li><li>支持粘贴 Cookie 与手机扫码两种登录方式</li><li>多套抽奖配置随时切换，口令、人数、频道、背景一起带走</li><li>深浅色与春节 / 假日背景，主色调随背景图自动取色</li><li>同一屏内查看直播画面与实时弹幕，弹幕贴底跟随、上滚暂停、静置后自动恢复</li></ul><h2 id="界面截图" tabindex="-1">界面截图 <a class="header-anchor" href="#界面截图" aria-label="Permalink to &quot;界面截图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>选人页</th><th>登录页</th><th>扫码登录</th></tr></thead><tbody><tr><td><img src="'+a+'" alt="选人页"></td><td><img src="'+r+'" alt="登录页"></td><td><img src="'+e+'" alt="扫码登录"></td></tr></tbody></table><table tabindex="0"><thead><tr><th>设置页</th><th>中奖结果</th><th>抽奖历史</th></tr></thead><tbody><tr><td><img src="'+i+'" alt="设置页"></td><td><img src="'+l+'" alt="中奖结果"></td><td><img src="'+d+'" alt="抽奖历史"></td></tr></tbody></table><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>技术</th></tr></thead><tbody><tr><td>后端</td><td>Wails v3 (v3.0.0-alpha.95) · Go 1.25</td></tr><tr><td>前端</td><td>React 19 · TypeScript 5 · Vite 6 · Tailwind 3 · HeroUI</td></tr><tr><td>直播协议</td><td>弹幕 WebSocket 二进制帧 · HLS（hls.js）</td></tr><tr><td>数据存储</td><td>本机 JSON（<code>~/.luckydraw/</code>）</td></tr></tbody></table><h2 id="数据留在本机" tabindex="-1">数据留在本机 <a class="header-anchor" href="#数据留在本机" aria-label="Permalink to &quot;数据留在本机&quot;">​</a></h2><p>登录凭证、配置与历史都写在 <code>~/.luckydraw/</code> 下，文件权限 0600，不上传任何服务器。应用本身也不提供云端同步、自动发奖等能力。</p>',14)])])}const D=o(n,[["render",p]]);export{g as __pageData,D as default};
